package week_02;

import java.awt.*;import javax.swing.*;
public class frm_AES extends JFrame {
 private final JTextField username=new JTextField("sinhvien01",22),ticket=new JTextField(40),key=new JTextField(32);
 private final JPasswordField password=new JPasswordField(22);private final JTextArea plain=new JTextArea(3,54),cipher=new JTextArea(3,54);private final JLabel status=new JLabel("Sẵn sàng.");private String currentUser;
 public frm_AES(){super("AES Cipher - Register / Login");setDefaultCloseOperation(DISPOSE_ON_CLOSE);ticket.setEditable(false);JPanel p=new JPanel();p.setBorder(BorderFactory.createEmptyBorder(16,20,16,20));p.setLayout(new BoxLayout(p,BoxLayout.Y_AXIS));JLabel h=new JLabel("AES-GCM - ĐĂNG KÝ / ĐĂNG NHẬP (SQLITE)");h.setFont(new Font("Segoe UI",Font.BOLD,18));p.add(h);
 JPanel auth=new JPanel(new FlowLayout(FlowLayout.LEFT));auth.add(new JLabel("Username:"));auth.add(username);auth.add(new JLabel("Password:"));auth.add(password);JButton connect=new JButton("Kết nối SQLite"),register=new JButton("Register"),login=new JButton("Login");connect.addActionListener(e->new frm_KetNoiSQL().setVisible(true));register.addActionListener(e->register());login.addActionListener(e->login());auth.add(connect);auth.add(register);auth.add(login);p.add(auth);
 JPanel tr=new JPanel(new FlowLayout(FlowLayout.LEFT));tr.add(new JLabel("Ticket:"));tr.add(ticket);p.add(tr);p.add(new JLabel("Plaintext:"));p.add(area(plain));JPanel kr=new JPanel(new FlowLayout(FlowLayout.LEFT));kr.add(new JLabel("Key AES:"));kr.add(key);kr.add(new JLabel("Mật khẩu tạo khóa AES-256"));p.add(kr);p.add(new JLabel("Ciphertext:"));p.add(area(cipher));JPanel buttons=new JPanel(new FlowLayout(FlowLayout.LEFT));JButton en=new JButton("Encrypt"),de=new JButton("Decrypt"),save=new JButton("Save File"),open=new JButton("Open File");en.addActionListener(e->crypt(true));de.addActionListener(e->crypt(false));save.addActionListener(e->save());open.addActionListener(e->open());buttons.add(en);buttons.add(de);buttons.add(save);buttons.add(open);p.add(buttons);p.add(status);setContentPane(p);pack();setMinimumSize(new Dimension(780,500));setLocationRelativeTo(null);}
 private JScrollPane area(JTextArea a){a.setLineWrap(true);a.setWrapStyleWord(true);return new JScrollPane(a);}
 private void register(){try{String u=username.getText().trim();UserDao.register(u,password.getPassword());HistoryDao.tryInsert("AES","REGISTER",u,0,0);status.setText("Register thành công: "+u+". Bấm Login.");}catch(Exception e){JOptionPane.showMessageDialog(this,e.getMessage(),"Đăng ký lỗi",JOptionPane.ERROR_MESSAGE);}}
 private void login(){try{String u=username.getText().trim();if(UserDao.login(u,password.getPassword())){currentUser=u;ticket.setText(UserDao.newTicket());HistoryDao.tryInsert("AES","LOGIN",u,0,0);status.setText("Login thành công: "+u+".");}else{currentUser=null;ticket.setText("");JOptionPane.showMessageDialog(this,"Sai username hoặc mật khẩu.");}}catch(Exception e){JOptionPane.showMessageDialog(this,e.getMessage(),"Đăng nhập lỗi",JOptionPane.ERROR_MESSAGE);}}
 private void crypt(boolean enc){if(currentUser==null){JOptionPane.showMessageDialog(this,"Hãy Login trước khi dùng AES.");return;}try{if(enc){if(plain.getText().isEmpty())throw new IllegalArgumentException("Hãy nhập Plaintext trước khi mã hóa.");cipher.setText(AESCipher.encrypt(plain.getText(),key.getText()));status.setText("Đã mã hóa AES-GCM. "+HistoryDao.tryInsert("AES","ENCRYPT",currentUser,plain.getText().length(),cipher.getText().length()));}else{plain.setText(AESCipher.decrypt(cipher.getText(),key.getText()));status.setText("Đã giải mã AES-GCM. "+HistoryDao.tryInsert("AES","DECRYPT",currentUser,cipher.getText().length(),plain.getText().length()));}}catch(Exception e){JOptionPane.showMessageDialog(this,"Thao tác AES thất bại: "+e.getMessage(),"Lỗi",JOptionPane.ERROR_MESSAGE);}}
 private void save(){String f=FileTextIO.save(this,cipher.getText(),"aes_ciphertext.txt");if(f!=null)status.setText("Đã lưu: "+f);}private void open(){String f=FileTextIO.open(this);if(f!=null)cipher.setText(f.trim());}
}
